import os, glob
from pathlib import Path
# search recursively from cwd for payments.csv
cwd = Path(os.getcwd())
matches = list(cwd.rglob('payments.csv'))
print('matches from cwd:', matches)
# also try common dirs
for root in [cwd, cwd / 'data', cwd / 'context', cwd.parent, cwd.parent / 'data']:
    if root.exists():
        for p in sorted(root.iterdir()):
            if p.is_file():
                print('File:', p)
            elif p.is_dir():
                print('Dir:', p)
